  assert len(e['proposed_quote'])>=12 and e['proposed_quote'] in raw(y['proposed_xml'])
for k,t in r['targets'].items():
 v=t['proposed_xml'] if t['view_kind']=='proposal' else t['source_xml']
 assert hashlib.sha256(v.encode()).hexdigest()==t['view_sha256'],t['number']
by={x['number']:x for x in a}
for number,marker in [('L243-6-3','<p>IV.-'),('L243-6','<p>III. -')]:
 original=next(x for x in s if x['number']==number)['source_xml']
 assert by[number]['proposed_xml'].split(marker)[0].strip()==original.split(marker)[0].strip()
for n in ['L243-5','L242-13']:
 print(n,by[n]['proposed_xml'])
print('Contrôles de structure et de traçabilité réussis : 24 articles,',sum(len(x['reference_checks']) for x in a),'renvois,',sum(len(x['substantive_impact']['effects']) for x in a),'effets documentés.')
